const ticket = $input.item.json.body ?? {};

const errors = [];

const ticketId = ticket.ticketId;
const customerEmail = ticket.customerEmail;
const message = ticket.message;

// Validate ticket ID
if (
  typeof ticketId !== "string" ||
  ticketId.trim() === ""
) {
  errors.push("Invalid ticket ID");
}

// Validate customer email
if (
  typeof customerEmail !== "string" ||
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)
) {
  errors.push("Invalid customer email");
}

// Validate ticket message
if (
  typeof message !== "string" ||
  message.trim() === ""
) {
  errors.push("Invalid ticket message");
}

return {
  json: {
    ticketId: typeof ticketId === "string"
      ? ticketId.trim()
      : null,
    customerEmail: typeof customerEmail === "string"
      ? customerEmail.trim()
      : null,
    message: typeof message === "string"
      ? message.trim()
      : null,
    isValid: errors.length === 0,
    errors,
    status: errors.length === 0
      ? "VALIDATED"
      : "VALIDATION_ERROR"
  }
};

const ticket = $('Validate Ticket').item.json;
const ai = $input.item.json;
const allowedCategories = ['SHIPPING', 'REFUND', 'BILLING', 'GENERAL'];
function output(classification, httpStatus, processingStatus) {
  return { json: { ...ticket, classification, httpStatus, processingStatus } };
}
// Ollama continues failures as an error item. Do not return raw error details.
if (Object.prototype.hasOwnProperty.call(ai, 'error')) {
  return output({ category: 'UNKNOWN', reason: '', isValid: false,
    requiresReview: true, errorCode: 'AI_UNAVAILABLE' }, 503, 'AI_UNAVAILABLE');
}
try {
  const parsed = typeof ai.content === 'string' ? JSON.parse(ai.content) : ai.content;
  const valid = parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)
    && allowedCategories.includes(parsed.category)
    && typeof parsed.reason === 'string'
    && parsed.reason.trim().length > 0 && parsed.reason.trim().length <= 500;
  const uncertain = parsed?.uncertain === true || parsed?.confidence === 'low' || /\b(?:cannot determine|unable to classify|uncertain whether|not enough information to classify)\b/i.test(parsed?.reason || '');
  if (valid && !uncertain) {
    return output({ category: parsed.category, reason: parsed.reason.trim(),
      isValid: true, requiresReview: false }, 200, 'CLASSIFIED');
  }
} catch {
  // Discard untrusted model output and parser details.
}
return output({ category: 'UNKNOWN', reason: '', isValid: false,
  requiresReview: true, errorCode: 'INVALID_AI_OUTPUT' }, 200, 'CLASSIFICATION_REVIEW_REQUIRED');

const ticket = $input.item.json;

// Only already-validated tickets may enter the future persistence path.
if (ticket.isValid !== true) {
  throw new Error('Prepare Ticket Claim requires a valid ticket');
}

for (const field of ['ticketId', 'customerEmail', 'message']) {
  if (typeof ticket[field] !== 'string' || ticket[field].trim().length === 0) {
    throw new Error('Prepare Ticket Claim requires nonempty ticket fields');
  }
}

// MySQL VARCHAR limits count characters, including one character per emoji.
if (Array.from(ticket.ticketId).length > 128) {
  throw new Error('ticketId exceeds the 128-character database limit');
}
if (Array.from(ticket.customerEmail).length > 254) {
  throw new Error('customerEmail exceeds the 254-character database limit');
}

// MySQL TEXT is limited to 65,535 bytes; Unicode characters may use multiple bytes.
if (Buffer.byteLength(ticket.message, 'utf8') > 65535) {
  throw new Error('message exceeds the 65535-byte database limit');
}

// Fingerprint contract: JSON array in this exact order, using the values already
// normalized by Validate Ticket. Preserve case and content; do not trim again.
// Exclude policy version, execution ID and timestamps so retries remain stable.
const fingerprintInput = JSON.stringify([
  ticket.ticketId,
  ticket.customerEmail,
  ticket.message,
]);

return {
  json: {
    ...ticket,
    fingerprintInput,
    policyVersion: 'demo-escalation-v2',
  },
};

const input = $input.item;
let ticket;
try { ticket = $('Fingerprint Ticket').item.json; }
catch { return { json: { claimOutcome: 'FAILURE', httpStatus: 503, errorCode: 'TICKET_CLAIM_FAILED' } }; }
const prepared = {
  ticketId: ticket.ticketId, customerEmail: ticket.customerEmail, message: ticket.message,
  isValid: ticket.isValid, errors: ticket.errors, status: ticket.status,
  payloadFingerprint: ticket.payloadFingerprint, policyVersion: ticket.policyVersion,
};
const row = input.json;
if (input.error === undefined && !Object.prototype.hasOwnProperty.call(row, 'error')
    && row.ticket_id === ticket.ticketId && typeof row.payload_fingerprint === 'string') {
  if (row.claim_outcome === 'NEW' && row.execution_id === String($execution.id)
      && row.payload_fingerprint === ticket.payloadFingerprint
      && row.processing_status === 'PROCESSING' && Number(row.claim_audit_rows) === 1) {
    return { json: { ...prepared, claimOutcome: 'NEW' } };
  }
  if (row.claim_outcome === 'DUPLICATE' && row.execution_id !== String($execution.id)
      && Number(row.claim_audit_rows) === 0) {
    return { json: { ...prepared, claimOutcome: 'DUPLICATE' } };
  }
}
// A 1062 error (including audit collisions) is a failure, never proof of a duplicate.
return { json: { ...prepared, claimOutcome: 'FAILURE', httpStatus: 503, errorCode: 'TICKET_CLAIM_FAILED' } };

const incoming = $('Fingerprint Ticket').item.json;
const row = $input.item.json;
if (row.ticket_id !== incoming.ticketId || typeof row.payload_fingerprint !== 'string') {
  return { json: { httpStatus: 503, errorCode: 'TICKET_LOOKUP_FAILED', ...incoming } };
}
if (row.payload_fingerprint !== incoming.payloadFingerprint) {
  return { json: { ticketId: incoming.ticketId, customerEmail: incoming.customerEmail,
    message: incoming.message, httpStatus: 409, errorCode: 'TICKET_ID_CONFLICT' } };
}
return { json: { resultKind: 'REPLAY', row } };

const ticket = $('Fingerprint Ticket').item.json;
const result = $input.item.json;
const c = result.classification || {};
const valid = c.isValid === true && ['SHIPPING','REFUND','BILLING','GENERAL'].includes(c.category)
  && typeof c.reason === 'string' && c.reason.trim().length > 0 && c.reason.trim().length <= 500;
const unavailable = c.errorCode === 'AI_UNAVAILABLE' || result.httpStatus === 503;
const policy = result.policyDecision;
// Missing or inconsistent policy results must never permit automatic routing.
const policyValid = policy && ['AUTO_ROUTED','PENDING_REVIEW','FAILED'].includes(policy.outcome)
  && Array.isArray(policy.codes) && policy.codes.every(code=>/^[A-Z_]{1,64}$/.test(code))
  && policy.codes.length<=12 && typeof policy.reviewReason==='string' && policy.reviewReason.length<=500
  && (policy.outcome==='AUTO_ROUTED' ? policy.requiresReview===false && policy.codes.length===0 && !policy.reviewReason
      : policy.outcome==='PENDING_REVIEW' ? policy.requiresReview===true && policy.codes.length>0 && !!policy.reviewReason : unavailable);
const review = !valid || !policyValid || policy.outcome !== 'AUTO_ROUTED';
const processingStatus = unavailable ? 'FAILED' : review ? 'PENDING_REVIEW' : 'AUTO_ROUTED';
const codes = unavailable ? [] : !policyValid ? ['POLICY_CHECK_FAILED'] : policy.codes;
return {json:{ticketId:ticket.ticketId,customerEmail:ticket.customerEmail,message:ticket.message,
 payloadFingerprint:ticket.payloadFingerprint,policyVersion:ticket.policyVersion,executionId:String($execution.id),
 category:valid&&!unavailable?c.category:'UNKNOWN',reason:valid&&!unavailable?c.reason.trim():'',
 requiresReview:processingStatus==='PENDING_REVIEW'?'1':'0',
 reviewReason:unavailable?'AI_UNAVAILABLE':review?(!policyValid?'Required business-policy checks could not be completed.':policy.reviewReason):'',
 processingStatus,policyCodes:JSON.stringify(codes),
 auditEvent:unavailable?'MODEL_UNAVAILABLE':review?'HUMAN_REVIEW_REQUESTED':'AI_CLASSIFICATION_ACCEPTED',
 eventKey:'FINAL_OUTCOME:'+ticket.policyVersion}};

let ticket = {};
try { ticket = $('Validate Ticket').item.json; } catch {}
const input = $input.item;
const rawMessage = input.error?.message || input.json.error?.message || input.json.error || input.json.message;
// Code-node errors append a line number. Strip only that suffix before allowlisting.
const message = typeof rawMessage === 'string' ? rawMessage.replace(/ \[line \d+\]$/, '') : '';
const lengthErrors = [
  'ticketId exceeds the 128-character database limit',
  'customerEmail exceeds the 254-character database limit',
  'message exceeds the 65535-byte database limit',
];
const invalidLength = lengthErrors.includes(message);
return { json: {
  ticketId: ticket.ticketId, customerEmail: ticket.customerEmail, message: ticket.message,
  httpStatus: invalidLength ? 400 : 503,
  errorCode: invalidLength ? 'TICKET_FIELD_TOO_LONG' : 'TICKET_PROCESSING_UNAVAILABLE',
  validationErrors: invalidLength ? [message] : [],
} };

const data = $input.item.json;
function failure(code = 'TICKET_PROCESSING_UNAVAILABLE') {
  let ticket = {};
  try { ticket = $('Validate Ticket').item.json; } catch {}
  return { json: { ticketId: ticket.ticketId, customerEmail: ticket.customerEmail,
    message: ticket.message, status: 'SERVICE_UNAVAILABLE', errorCode: code, httpStatus: 503 } };
}
try {
  if ([400, 409, 503].includes(data.httpStatus)) {
    const allowed = ['TICKET_FIELD_TOO_LONG', 'TICKET_ID_CONFLICT', 'TICKET_LOOKUP_FAILED',
      'TICKET_CLAIM_FAILED', 'CLAIM_CONTEXT_UNAVAILABLE', 'TICKET_PROCESSING_UNAVAILABLE'];
    const code = allowed.includes(data.errorCode) ? data.errorCode : 'TICKET_PROCESSING_UNAVAILABLE';
    return { json: { ticketId: data.ticketId, customerEmail: data.customerEmail,
      message: data.message, status: data.httpStatus === 409 ? 'CONFLICT'
        : data.httpStatus === 400 ? 'VALIDATION_ERROR' : 'SERVICE_UNAVAILABLE',
      errorCode: code, ...(data.httpStatus === 400 ? { isValid: false, errors: data.validationErrors || [] } : {}),
      httpStatus: data.httpStatus } };
  }
  const replay = data.resultKind === 'REPLAY';
  const row = replay ? data.row : data;
  if (!replay && (Number(row.updated_rows) !== 1 || Number(row.audit_rows) !== 1)) return failure('TICKET_PROCESSING_UNAVAILABLE');
  if (!row || typeof row.ticket_id !== 'string') return failure();
  const fields = { ticketId: row.ticket_id, customerEmail: row.customer_email, message: row.customer_message };
  if (row.processing_status === 'PROCESSING') {
    return { json: { ...fields, status: 'PROCESSING', processingStatus: 'PROCESSING', httpStatus: 202 } };
  }
  if (row.processing_status === 'FAILED') {
    return { json: { ...fields, status: 'SERVICE_UNAVAILABLE', errorCode: 'AI_UNAVAILABLE', httpStatus: 503 } };
  }
  if (row.processing_status === 'PENDING_REVIEW') {
    return { json: { ...fields, isValid: true, errors: [], status: 'PENDING_REVIEW',
      classification: {category:row.classification_category || 'UNKNOWN',reason:row.classification_reason || '',isValid:['SHIPPING','REFUND','BILLING','GENERAL'].includes(row.classification_category),requiresReview:true},
      requiresReview:true,reviewReason:String(row.review_reason || 'Review required').slice(0,500),
      processingStatus: 'PENDING_REVIEW', httpStatus: 202 } };
  }
  if (row.processing_status === 'REJECTED') {
    return { json: { ...fields, isValid: true, errors: [], status: 'REJECTED',
      processingStatus: 'REJECTED', httpStatus: 200 } };
  }
  if (row.processing_status === 'APPROVED') {
    if (!['SHIPPING','REFUND','BILLING','GENERAL'].includes(row.classification_category)
        || typeof row.classification_reason !== 'string' || !row.classification_reason.trim()) return failure();
    return { json: { ...fields, isValid: true, errors: [], status: 'APPROVED',
      classification: { category: row.classification_category, reason: row.classification_reason,
        isValid: true, requiresReview: false }, processingStatus: 'APPROVED', httpStatus: 200 } };
  }
  if (row.processing_status !== 'AUTO_ROUTED' || !['SHIPPING','REFUND','BILLING','GENERAL'].includes(row.classification_category)
      || typeof row.classification_reason !== 'string' || !row.classification_reason.trim()) return failure();
  return { json: { ...fields, isValid: true, errors: [], status: 'VALIDATED',
    classification: { category: row.classification_category, reason: row.classification_reason,
      isValid: true, requiresReview: false }, httpStatus: 200, processingStatus: 'CLASSIFIED' } };
} catch { return failure(); }

const config = {
  "version": "demo-escalation-v2",
  "refundThreshold": null,
  "refundCurrency": null,
  "symbolCurrencies": {},
  "rules": {
    "approvalClaims": true,
    "monetaryRefunds": true,
    "policyExceptions": true,
    "fraudAllegations": true,
    "legalThreats": true,
    "seriousDisputes": true
  }
};
function evaluateEscalation(message, classification, config) {
  const reasons = new Set();
  const descriptions = {
    UNVERIFIED_APPROVAL: 'Unverified manager or supervisor approval claim.',
    REFUND_POLICY_UNCONFIGURED: 'Monetary refund claim requires review: refund threshold or currency policy is not configured.',
    REFUND_AMOUNT_UNVERIFIABLE: 'Monetary refund amount or currency could not be verified.',
    HIGH_VALUE_REFUND: 'Requested refund exceeds the configured monetary threshold.',
    POLICY_EXCEPTION: 'Request for an exception to company policy.',
    FRAUD_ALLEGATION: 'Fraud or unauthorized-payment allegation.',
    LEGAL_THREAT: 'Legal action threatened or reported.',
    SERIOUS_DISPUTE: 'Formal payment dispute or chargeback.',
    INVALID_AI_OUTPUT: 'AI classification is unsupported, malformed, or uncertain.',
    POLICY_CHECK_FAILED: 'Required business-policy checks could not be completed.',
  };
  const allowed = ['SHIPPING', 'REFUND', 'BILLING', 'GENERAL'];
  const valid = classification?.isValid === true && allowed.includes(classification.category)
    && typeof classification.reason === 'string' && classification.reason.trim().length > 0
    && classification.reason.trim().length <= 500;
  // An unavailable model is an infrastructure failure, never a review fallback.
  if (classification?.errorCode === 'AI_UNAVAILABLE') {
    return { outcome: 'FAILED', requiresReview: false, codes: [], reviewReason: 'AI_UNAVAILABLE' };
  }
  if (!valid) reasons.add('INVALID_AI_OUTPUT');
  try {
    if (typeof message !== 'string' || !config || typeof config.version !== 'string' || !/^[a-zA-Z0-9._-]{1,32}$/.test(config.version)) throw Error('POLICY_CONFIG');
    for (const rule of ['approvalClaims','monetaryRefunds','policyExceptions','fraudAllegations','legalThreats','seriousDisputes']) {
      if (typeof config.rules?.[rule] !== 'boolean') throw Error('POLICY_RULE_CONFIG');
    }
    const thresholdReady = Number.isFinite(config.refundThreshold) && config.refundThreshold >= 0
      && typeof config.refundCurrency === 'string' && /^[A-Z]{3}$/.test(config.refundCurrency);
    // Sentence/contrast scope keeps unrelated and explicitly hypothetical mentions separate.
    const clauses = message.split(/(?<=[.!?])\s+|[\n;]+|\bbut\b|\bhowever\b/i);
    for (const original of clauses) {
      const text = original.toLowerCase().replace(/[’]/g, "'").trim();
      const conditionalThreat = /\b(?:i|we)\s+(?:will|plan to|intend to)\s+(?:sue|file|take legal action)/.test(text);
      if (!text || (!conditionalThreat && (/^(?:if\b|hypothetically\b|suppose\b|for example\b|as an example\b|imagine\b)/.test(text)
          || /\b(?:hypothetical example|hypothetical scenario)\b/.test(text)))) continue;
      const approval = /\b(?:manager|supervisor)\b.{0,65}\b(?:approved|authorized|promised|signed off|agreed to)\b/.test(text)
        || /\b(?:approved|authorized|promised|signed off)\b.{0,40}\bby\s+(?:your |the |a |my |our )?(?:manager|supervisor)\b/.test(text);
      const approvalDenied = /\b(?:not|never|hasn't|hadn't|haven't|didn't|wasn't|weren't)\s+(?:been\s+)?(?:approved|authorized|promised|signed off|agreed)\b/.test(text)
        || /\b(?:no|neither)\s+(?:manager|supervisor)\b/.test(text);
      const approvalQuestion = /^(?:has|have|did|can|could|would|will)\s+(?:your |the |a |my |our )?(?:manager|supervisor)\b/.test(text)
        || /\b(?:whether|if)\s+(?:your |the |a |my |our )?(?:manager|supervisor)\b/.test(text);
      const approvalContext = /\b(?:refund|return|replacement|credit|discount|exception|payment|reimburse|request|claim|waiver)\b/.test(text) || /\b(?:approved|authorized)\s+(?:it|this)\b/.test(text);
      if (config.rules.approvalClaims && approval && approvalContext && !approvalDenied && !approvalQuestion) reasons.add('UNVERIFIED_APPROVAL');
      if (config.rules.fraudAllegations && /\b(?:fraud|fraudulent|scam|scammed|unauthori[sz]ed\s+(?:charge|payment|transaction))\b/.test(text)
          && !/\b(?:not|no|never|isn't|wasn't)\s+(?:a\s+)?(?:fraud|fraudulent|scam|scammed|unauthori[sz]ed)\b/.test(text)
          && !/\b(?:prevent|avoid|prevention|learn about|what is)\b/.test(text)) reasons.add('FRAUD_ALLEGATION');
      if (config.rules.legalThreats && /\b(?:sue|suing|lawsuit|legal action|my lawyer|my attorney)\b/.test(text)
          && /\b(?:i|we|my|our|will|plan|intend|file|filing|take|taking|contact|contacting)\b/.test(text)
          && !/\b(?:not|never|won't|will not|don't|do not)\b.{0,25}\b(?:sue|suing|file|filing|take|taking|legal action|lawyer|attorney)\b/.test(text)) reasons.add('LEGAL_THREAT');
      if (config.rules.seriousDisputes && /\b(?:chargeback|formal dispute|disput(?:e|ing) (?:this|the|a|my) (?:charge|payment|transaction))\b/.test(text)
          && !/\b(?:no|not|never|won't|will not|don't|do not)\b.{0,25}\b(?:chargeback|formal dispute|disput)/.test(text)
          && !/\b(?:what is|explain|definition|prevent|avoid)\b/.test(text)) reasons.add('SERIOUS_DISPUTE');
      if (config.rules.policyExceptions && /\b(?:make|request|grant|allow|want|need|asking for)\b.{0,35}\b(?:an? )?exception\b|\b(?:waive|bypass|ignore|override)\b.{0,25}\b(?:policy|rule|return window|deadline)\b/.test(text)
          && !/\b(?:not|never|don't|do not|no)\b.{0,20}\b(?:request|need|want|asking|make|exception|waive|bypass|ignore|override)\b/.test(text)) reasons.add('POLICY_EXCEPTION');
      // A price mention or a general refund-policy question is not a refund claim.
      const refundIntent = /\brefund\b/.test(text) && /\b(?:request|requesting|want|need|seeking|issue|process|approve|approved|authorized|promised|owed|refund me|refund of)\b/.test(text)
        && !/\b(?:not|never|don't|do not|no)\b.{0,20}\b(?:want|need|request|requesting|seeking|refund|owed)\b/.test(text);
      if (config.rules.monetaryRefunds && refundIntent) {
        const amounts = [...original.matchAll(/(USD|EUR|GBP|CAD|AUD|\$|€|£)\s*(\d[\d,]*(?:\.\d+)?)|(\d[\d,]*(?:\.\d+)?)\s*(USD|EUR|GBP|CAD|AUD|dollars?|euros?|pounds?)/gi)];
        for (const match of amounts) {
          if (!thresholdReady) { reasons.add('REFUND_POLICY_UNCONFIGURED'); continue; }
          const token = (match[1] || match[4]).toUpperCase(), raw = match[2] || match[3];
          const currency = /^[A-Z]{3}$/.test(token) ? token : config.symbolCurrencies?.[token];
          if (!/^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d{1,2})?$/.test(raw) || currency !== config.refundCurrency) {
            reasons.add('REFUND_AMOUNT_UNVERIFIABLE'); continue;
          }
          const amount = Number(raw.replaceAll(',', ''));
          if (!Number.isFinite(amount)) reasons.add('REFUND_AMOUNT_UNVERIFIABLE');
          else if (amount > config.refundThreshold) reasons.add('HIGH_VALUE_REFUND');
        }
        if (!amounts.length && /[$€£]|\b(?:dollars?|euros?|pounds?|USD|EUR|GBP|CAD|AUD)\b/i.test(original)) reasons.add('REFUND_AMOUNT_UNVERIFIABLE');
      }
    }
  } catch { reasons.add('POLICY_CHECK_FAILED'); }
  const codes = [...reasons].sort();
  return { outcome: codes.length ? 'PENDING_REVIEW' : 'AUTO_ROUTED', requiresReview: !!codes.length,
    codes, reviewReason: codes.map(code => descriptions[code]).join(' ').slice(0,500) };
}
const result = $input.item.json;
const ticket = $('Fingerprint Ticket').item.json;
return {json:{...result, policyDecision:evaluateEscalation(ticket.message,result.classification,config)}};
